// Deterministic 'world': search_orders returns rows only on the 4th distinct query.
// No Math.random, no Date — fully scripted.
const WORLD = {
  '': [],
  'status:open': [],
  'status:open region:eu': [],
  'status:open region:eu year:2024': [{ id: 7, total: 42 }],
};
function search_orders(query) {
  return WORLD[query] || [];
}
// The plan the model 'decides' on each step (scripted for determinism):
const PLAN = ['', 'status:open', 'status:open', 'status:open region:eu', 'status:open region:eu year:2024'];

function runAgent(maxSteps) {
  let steps = 0;
  let prevQuery = null;
  let outcome = 'unknown';
  for (let i = 0; i < PLAN.length; i++) {
    if (steps >= maxSteps) { outcome = 'max-steps'; break; }
    const query = PLAN[i];
    // dedup / thrash guard: identical consecutive call
    if (query === prevQuery) { outcome = 'thrash'; break; }
    steps++;
    const rows = search_orders(query);
    prevQuery = query;
    if (rows.length > 0) { outcome = 'goal'; break; }
  }
  return { outcome, steps };
}
